changeSet.sql:
ALTER TABLE trades RENAME TO trades_old;
CREATE TABLE trades ( id BIGINT GENERATED BY DEFAULT AS IDENTITY, trade_ref VARCHAR(30) NOT NULL, instrument_id BIGINT NOT NULL, counterparty_id BIGINT NOT NULL, asset_class VARCHAR(20) NOT NULL, side VARCHAR(4) NOT NULL, quantity NUMERIC(18,4) NOT NULL, price NUMERIC(18,4) NOT NULL, trade_date DATE NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', deleted_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT now(), modified_at TIMESTAMPTZ,
PRIMARY KEY(id, trade_date),
CONSTRAINT fk_trades_instrument FOREIGN KEY(instrument_id) REFERENCES instruments(id),
CONSTRAINT fk_trades_counterparty FOREIGN KEY(counterparty_id) REFERENCES counterparties(id)
) PARTITION BY RANGE(trade_date);
CREATE TABLE trades_y2026m04 PARTITION OF trades FOR VALUES FROM ('2026-04-01') TO ('2026-05-01');
CREATE TABLE trades_y2026m05 PARTITION OF trades FOR VALUES FROM ('2026-05-01') TO ('2026-06-01');
CREATE TABLE trades_y2026m06 PARTITION OF trades FOR VALUES FROM ('2026-06-01') TO ('2026-07-01');
CREATE TABLE trades_y2026m07 PARTITION OF trades FOR VALUES FROM ('2026-07-01') TO ('2026-08-01');
CREATE TABLE trades_default PARTITION OF trades DEFAULT;
CREATE INDEX IF NOT EXISTS idx_trades_status ON trades(status);
CREATE INDEX IF NOT EXISTS idx_trades_instrument ON trades(instrument_id);
CREATE INDEX IF NOT EXISTS idx_trades_counterparty ON trades(counterparty_id);
INSERT INTO trades SELECT * FROM trades_old;
